/* Perjanjian Rimba — original canvas platformer, no runtime dependencies. */
const $=id=>document.getElementById(id),canvas=$('game'),ctx=canvas.getContext('2d');
let mode='intro',keys={},p,cam=0,t=0,last=0,seals,enemies,boss,shots=[],sparks=[],summon=0,cooldown=0,attackCD=0,invul=0,checkpoint=80,toastTime=0,sound=false,audio;
const W=1200,H=560,ground=476,world=4400;
const platforms=[{x:0,y:476,w:910},{x:1020,y:476,w:830},{x:1960,y:476,w:740},{x:2810,y:476,w:1590},{x:330,y:380,w:160},{x:600,y:302,w:170},{x:900,y:381,w:180},{x:1250,y:367,w:160},{x:1510,y:291,w:160},{x:1790,y:387,w:180},{x:2140,y:366,w:170},{x:2390,y:288,w:170},{x:2680,y:383,w:180},{x:3060,y:376,w:180}];
function reset(){p={x:80,y:400,w:27,h:49,vx:0,vy:0,hp:5,dir:1,jumps:0};seals=[{x:678,y:264,got:false},{x:1585,y:252,got:false},{x:2475,y:249,got:false}];enemies=[{x:720,y:440,hp:3,home:720},{x:1350,y:440,hp:3,home:1350},{x:2220,y:440,hp:3,home:2220},{x:3130,y:440,hp:3,home:3130}];boss={x:4030,y:386,hp:45,max:45,cd:2,active:false,flash:0};shots=[];sparks=[];summon=0;cooldown=0;invul=0;attackCD=0;checkpoint=80;cam=0;t=0;updateHUD()}
function tone(freq=440,dur=.1,type='sine'){if(!sound)return;try{audio??=new (window.AudioContext||window.webkitAudioContext)();audio.resume();let o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.setValueAtTime(freq,audio.currentTime);g.gain.setValueAtTime(.045,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+dur);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+dur)}catch{}}
function toast(s){$('toast').textContent=s;toastTime=3.7;$('toast').style.opacity=1}
function overlay(tag,title,desc,label,note=''){keys={};$('overlayTag').textContent=tag;$('overlayTitle').innerHTML=title;$('overlayText').textContent=desc;$('start').innerHTML=label+' <span>→</span>';$('overlayNote').textContent=note;$('overlay').hidden=false}
function start(){if(mode==='paused'){mode='playing';$('overlay').hidden=true}else{reset();mode='playing';$('overlay').hidden=true;toast('Irma: “Lukman, ayo bawa pulang Jantung Rimba!”')}canvas.focus()}
function pause(){if(mode==='playing'){mode='paused';overlay('ISTIRAHAT SEJENAK','Rimba menantimu.','Petualanganmu tersimpan selama halaman ini terbuka.','Lanjutkan')}else if(mode==='paused')start()}
function act(k){if(k==='escape'){pause();return}if(mode!=='playing')return;if(k===' '||k==='w'||k==='arrowup'){if(p.jumps<2){p.vy=-570;p.jumps++;burst(p.x+12,p.y+49,'#c7eaa2',7);tone(380+p.jumps*100)}}if(k==='j')attack();if(k==='e'&&cooldown<=0){summon=10;cooldown=17;toast('Lukman: “Serahkan musuhnya padaku, Irma!”');tone(700,.3);burst(p.x-30,p.y+20,'#b6f48c',24)}}
function attack(){if(attackCD>0)return;attackCD=.28;shots.push({x:p.x+14+p.dir*20,y:p.y+21,vx:p.dir*640,life:1.05,ally:false});tone(270,.09,'triangle')}
function burst(x,y,color,n=12){for(let i=0;i<n;i++)sparks.push({x,y,vx:(Math.random()-.5)*220,vy:(Math.random()-.5)*220,life:.35+Math.random()*.4,color})}
function hurt(){if(invul>0||mode!=='playing')return;p.hp--;invul=1.4;p.vy=-260;burst(p.x,p.y+20,'#eea18f');tone(100,.2,'sawtooth');if(p.hp<=0){mode='dead';overlay('PERJALANAN BELUM USAI','Bangkit lagi, Irma.','Hutan masih membutuhkanmu. Coba lompat melewati serangan dan panggil Lukman saat musuh mendekat.','Coba lagi')}updateHUD()}
function updateHUD(){let n=seals.filter(s=>s.got).length;$('hearts').textContent='♥ '.repeat(Math.max(0,p.hp))+'♡ '.repeat(5-Math.max(0,p.hp));$('hearts').setAttribute('aria-label',p.hp+' dari 5 nyawa');$('seals').textContent='◈ '+n+' / 3';let stage=p.x<1850?0:p.x<3500?1:2;$('chapter').textContent=['BAB I','BAB II','BAB III'][stage];$('location').textContent=['Hutan Berbisik','Jejak Perjanjian','Benteng Fahrudin'][stage];$('objective').textContent=n<3?'Misi: kumpulkan 3 segel rimba':'Misi: kalahkan Ogre Fahrudin';$('summonStatus').textContent=summon>0?'✦ LUKMAN BERSAMAMU · '+Math.ceil(summon)+' dtk':cooldown>0?'✦ LUKMAN PULIH · '+Math.ceil(cooldown)+' dtk':'✦ LUKMAN SIAP DIPANGGIL [E]';$('bossbar').hidden=!boss.active||mode==='won';$('bosshealth').style.width=Math.max(0,boss.hp/boss.max*100)+'%'}
let allyCD=0;
function update(dt){t+=dt;invul-=dt;attackCD-=dt;cooldown=Math.max(0,cooldown-dt);summon=Math.max(0,summon-dt);allyCD-=dt;toastTime-=dt;if(toastTime<=0)$('toast').style.opacity=0;
let dir=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0);p.vx=dir*270;if(dir)p.dir=dir;if(keys.j)attack();p.x=Math.max(0,Math.min(world-p.w,p.x+p.vx*dt));const prev=p.y+p.h;p.vy+=1450*dt;p.y+=p.vy*dt;for(const f of platforms){if(p.x+p.w>f.x&&p.x<f.x+f.w&&prev<=f.y+3&&p.y+p.h>=f.y&&p.vy>=0){p.y=f.y-p.h;p.vy=0;p.jumps=0}}if(p.y>660){hurt();p.x=checkpoint;p.y=380;p.vy=0;p.jumps=0}
for(const s of seals){if(!s.got&&Math.hypot(p.x+14-s.x,p.y+24-s.y)<46){s.got=true;p.hp=Math.min(5,p.hp+1);checkpoint=s.x-40;burst(s.x,s.y,'#e0efa5',30);tone(880,.35);toast(seals.every(a=>a.got)?'Tiga segel terkumpul! Fahrudin menunggu di timur.':'Segel rimba ditemukan. Satu nyawa dipulihkan.')}}
for(const e of enemies){if(e.hp<=0)continue;e.x+=Math.sin(t+e.home)*34*dt;if(Math.abs(p.x-e.x)<33&&Math.abs(p.y+25-e.y)<44)hurt()}
if(p.x>3530&&!boss.active){if(seals.every(s=>s.got)){boss.active=true;checkpoint=3460;p.hp=5;toast('Fahrudin: “Jantung Rimba ini milikku!”')}else{p.x=3518;toast('Gerbang tertutup. Temukan ketiga segel di platform atas.')}}
if(boss.active&&boss.hp>0){boss.flash-=dt;boss.x+=Math.sign(p.x-boss.x)*64*dt;boss.x=Math.max(3650,Math.min(4270,boss.x));boss.cd-=dt;if(Math.abs(p.x-boss.x)<61&&p.y+p.h>boss.y+18)hurt();if(boss.cd<=0){boss.cd=boss.hp<20?1.1:1.8;shots.push({x:boss.x,y:454,vx:-260,life:5,enemy:true});burst(boss.x,ground,'#e6ae7d',15);tone(80,.15)}}
if(summon>0&&allyCD<=0){let targets=enemies.filter(e=>e.hp>0&&Math.abs(e.x-p.x)<600);if(boss.active&&Math.abs(boss.x-p.x)<650)targets.push(boss);targets.sort((a,b)=>Math.abs(a.x-p.x)-Math.abs(b.x-p.x));if(targets.length){let target=targets[0];allyCD=.5;shots.push({x:p.x-36,y:p.y+29,vx:Math.sign(target.x-p.x)*570,life:1.3,ally:true,target})}}
for(const s of shots){s.life-=dt;s.x+=s.vx*dt;if(s.ally&&s.target)s.y+=(s.target.y+10-s.y)*Math.min(1,dt*5);if(s.enemy){if(Math.abs(s.x-p.x-14)<24&&Math.abs(s.y-p.y-28)<29){hurt();s.life=0}}else{for(const e of enemies){if(e.hp>0&&Math.abs(s.x-e.x)<28&&Math.abs(s.y-e.y)<35){e.hp--;s.life=0;burst(e.x,e.y,'#b6ce85');break}}if(s.life>0&&boss.active&&boss.hp>0&&Math.abs(s.x-boss.x)<55&&s.y>boss.y-10&&s.y<480){boss.hp-=s.ally?2:1;boss.flash=.12;s.life=0;burst(s.x,s.y,'#f0cba3');if(boss.hp<=0){mode='won';tone(1000,.6);overlay('KUTUKAN TELAH TERPATAHKAN','Cahaya kembali ke rimba.','Fahrudin tumbang. Irma mengembalikan Jantung Rimba, dan desa kembali bercahaya. “Kita berhasil,” kata Irma. Lukman tersenyum: “Tim terbaik di seluruh rimba!”','Main lagi','TAMAT · IRMA SURYANI & LUKMAN')}}}}
shots=shots.filter(s=>s.life>0);for(const s of sparks){s.life-=dt;s.x+=s.vx*dt;s.y+=s.vy*dt;s.vy+=170*dt}sparks=sparks.filter(s=>s.life>0);cam=Math.max(0,Math.min(world-W,p.x-W*.34));updateHUD()}
function rect(x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(Math.round(x),Math.round(y),w,h)}
function tree(x,y,scale,c){ctx.fillStyle=c;ctx.beginPath();ctx.moveTo(x-18*scale,560);ctx.lineTo(x-11*scale,y+60*scale);ctx.lineTo(x-90*scale,y);ctx.lineTo(x-21*scale,y+30*scale);ctx.lineTo(x-32*scale,y-140*scale);ctx.lineTo(x-6*scale,y-70*scale);ctx.lineTo(x+15*scale,y-180*scale);ctx.lineTo(x+9*scale,y+23*scale);ctx.lineTo(x+92*scale,y-70*scale);ctx.lineTo(x+26*scale,y+57*scale);ctx.lineTo(x+40*scale,560);ctx.fill()}
function sprite(x,y,kind,dir=1){ctx.save();ctx.translate(Math.round(x),Math.round(y));ctx.scale(dir,1);let step=mode==='playing'&&kind!=='ogre'?Math.sin(t*13)*(kind==='irma'&&p.vx===0?0:3):0;if(kind==='irma'){rect(-17,15,32,31,'#233445');rect(-13,16,25,28,'#81a6aa');rect(-12,26,24,5,'#b9d0bd');rect(-9,42+step,7,9,'#263239');rect(4,42-step,7,9,'#263239');rect(-10,-2,22,23,'#313239');rect(-7,3,16,13,'#e7b99d');rect(-12,-2,23,7,'#202e36');rect(-12,0,6,22,'#23333b');rect(5,8,3,3,'#263a38');rect(13,20,5,18,'#ba9580');rect(18,5,4,42,'#826345');rect(14,0,12,12,'#bceab4');rect(18,-4,5,5,'#ecffc8')}else if(kind==='goblin'){rect(-9,18,19,17,'#8a714a');rect(-8,33+step,6,7,'#4d6050');rect(3,33-step,6,7,'#4d6050');rect(-12,0,26,21,'#9bc271');rect(-21,2,10,8,'#9bc271');rect(13,2,10,8,'#9bc271');rect(-7,7,5,4,'#e9efae');rect(5,7,5,4,'#e9efae');rect(-5,8,2,4,'#253b31');rect(7,8,2,4,'#253b31');rect(-2,15,7,2,'#43543b');rect(14,22,3,20,'#c7d5ad')}else if(kind==='ogre'){rect(-40,31,79,58,boss.flash>0?'#efd2ae':'#6f8162');rect(-45,53,88,22,'#594c3f');rect(-33,80,23,13,'#394a43');rect(13,80,23,13,'#394a43');rect(-30,0,61,41,'#9ba577');rect(-44,3,17,16,'#8f9a70');rect(29,3,17,16,'#8f9a70');rect(-24,-9,9,13,'#d4c8a2');rect(16,-9,9,13,'#d4c8a2');rect(-18,15,11,5,'#e6a479');rect(8,15,11,5,'#e6a479');rect(-13,31,27,6,'#414d3a');rect(-17,28,5,10,'#e8ddbb');rect(12,28,5,10,'#e8ddbb');rect(47,30,9,72,'#846445');rect(33,24,39,25,'#66736a')}else{rect(-16,4,32,29,'#684d6f');rect(-12,-8,25,23,'#9d7b94');rect(-17,-14,7,14,'#9d7b94');rect(9,-14,7,14,'#9d7b94');rect(-7,0,5,4,'#f1bb92');rect(4,0,5,4,'#f1bb92');rect(-12,30,8,8,'#3b374d');rect(6,30,8,8,'#3b374d')}ctx.restore()}
function draw(){ctx.clearRect(0,0,W,H);let g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#19333f');g.addColorStop(.6,'#355652');g.addColorStop(1,'#758d68');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);ctx.fillStyle='#cbd8a5';ctx.beginPath();ctx.arc(920-cam*.06,105,48,0,Math.PI*2);ctx.fill();ctx.fillStyle='#abc7aa12';ctx.beginPath();ctx.arc(920-cam*.06,105,85,0,Math.PI*2);ctx.fill();for(let i=0;i<18;i++)tree(i*120-cam*.16%120,200+(i%4)*20,.65,'#28484b');for(let i=0;i<11;i++)tree(i*170-70-cam*.35%170,110+(i%3)*43,1.1,'#1a3b3f');ctx.fillStyle='#d6edb709';for(let i=0;i<4;i++){ctx.beginPath();ctx.moveTo(700+i*90,0);ctx.lineTo(410+i*80,470);ctx.lineTo(530+i*80,470);ctx.lineTo(725+i*90,0);ctx.fill()}for(let i=0;i<45;i++){let x=(i*173.17-cam*.4+world)%1250,y=110+(i*71%340)+Math.sin(t+i)*8;rect(x,y,2,2,'#b9d69955')}
ctx.save();ctx.translate(-cam,0);for(const f of platforms){rect(f.x,f.y,f.w,H-f.y+30,'#243735');rect(f.x,f.y,f.w,7,'#859d6c');rect(f.x,f.y+7,f.w,9,'#536e50');for(let x=f.x+8;x<f.x+f.w-8;x+=25){rect(x,f.y-5-(x%7),3,8,'#779966');rect(x+4,f.y+22,12,4,'#35463b');rect(x+11,f.y+45,18,5,'#2d4038')}}for(let i=0;i<22;i++){let x=i*190+110;if(platforms.some(f=>f.y===ground&&x>f.x&&x<f.x+f.w)){rect(x,457,4,19,'#708572');rect(x-7,454,18,5,'#96bbb0');rect(x+7,449,3,8,'#afcab6')}}for(const s of seals){if(s.got)continue;const y=s.y+Math.sin(t*2+s.x)*5;ctx.fillStyle='#cbea8a18';ctx.beginPath();ctx.arc(s.x,y,30,0,Math.PI*2);ctx.fill();ctx.fillStyle='#d9f09b';ctx.beginPath();ctx.moveTo(s.x,y-15);ctx.lineTo(s.x+10,y);ctx.lineTo(s.x,y+15);ctx.lineTo(s.x-10,y);ctx.fill();rect(s.x-2,y-6,4,12,'#739d64')}
rect(3550,240,22,236,'#54695b');rect(3730,240,22,236,'#54695b');rect(3535,230,232,25,'#6b7e66');if(!boss.active&&!seals.every(s=>s.got)){for(let i=0;i<6;i++)rect(3578+i*27,255,4,221,'#9cba8270')}for(const e of enemies)if(e.hp>0)sprite(e.x,e.y-3,'enemy');if(boss.hp>0){sprite(boss.x,boss.y,'ogre');ctx.fillStyle='#ddc6a9';ctx.font='12px sans-serif';ctx.textAlign='center';ctx.fillText('OGRE FAHRUDIN',boss.x,boss.y-24)}if(invul<=0||Math.floor(t*15)%2===0)sprite(p.x+14,p.y,'irma',p.dir);if(summon>0){let x=p.x-42*p.dir,y=p.y+13+Math.sin(t*4)*3;sprite(x,y,'goblin',p.dir);ctx.font='10px sans-serif';ctx.fillStyle='#d0e9a6';ctx.textAlign='center';ctx.fillText('LUKMAN',x,y-13)}for(const s of shots){rect(s.x-10,s.y-5,20,10,s.enemy?'#e3a17a':s.ally?'#a5e67e':'#d4f5d2');rect(s.x-Math.sign(s.vx)*20,s.y-3,12,6,s.enemy?'#c0876255':'#c3efac55')}for(const s of sparks){ctx.globalAlpha=Math.max(0,s.life);rect(s.x,s.y,4,4,s.color)}ctx.globalAlpha=1;ctx.restore();rect(0,548,1200,12,'#102928');}
function frame(now){let dt=Math.min((now-last)/1000||0,.033);last=now;if(mode==='playing')update(dt);else t+=dt*.2;draw();requestAnimationFrame(frame)}
window.addEventListener('keydown',e=>{let k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright','a','d','w','j','e','escape'].includes(k)){if(e.target.tagName==='BUTTON'&&k===' ')return;e.preventDefault();if(!keys[k])act(k);keys[k]=true}});window.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);window.addEventListener('blur',()=>{keys={};if(mode==='playing')pause()});document.addEventListener('visibilitychange',()=>{if(document.hidden&&mode==='playing')pause()});for(const b of document.querySelectorAll('[data-key]')){b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);const k=b.dataset.key;act(k);keys[k]=true});b.addEventListener('pointerup',()=>keys[b.dataset.key]=false);b.addEventListener('pointercancel',()=>keys[b.dataset.key]=false)}$('start').onclick=start;$('pause').onclick=pause;$('sound').onclick=()=>{sound=!sound;$('sound').innerHTML='♪ <span>Suara '+(sound?'aktif':'mati')+'</span>';$('sound').setAttribute('aria-label',sound?'Matikan suara':'Aktifkan suara');tone(600)};reset();draw();requestAnimationFrame(frame);
if(document.modelContext?.registerTool){for(const tool of [{name:'read_adventure_state',description:'Read current adventure progress and health.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({status:mode,health:p.hp,seals:seals.filter(s=>s.got).length,bossHealth:boss.hp})},{name:'start_adventure',description:'Start a new adventure or resume the paused adventure.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(input&&Object.keys(input).length)throw Error('No arguments expected');if(mode==='playing')throw Error('Adventure already running');start();return{status:mode}}}]){try{Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{})}catch{}}}
